# filename: scripts/verify_store_down.py
"""Card [5] 'Done when' part 2: answers within budget while DynamoDB (and Kinesis) are unreachable.
Pauses LocalStack (state is kept), sends payments, unpauses, then checks the service recovers.
The finally block ALWAYS unpauses, even after Ctrl+C or a crash."""
import argparse, json, subprocess, time
from collections import Counter

from stepup_e2e import payment, post        # same folder: reuse the payment builder and POST helper

RT_LIMIT_MS = 500                           # far above normal; a jump here means something is blocking


def compose(action):
    subprocess.run(["docker", "compose", action, "localstack"], check=True)


def send_one(url, card, device):
    t0 = time.perf_counter()
    try:
        status, reply = post(url, payment(card, device, 1000))
    except OSError as e:                    # connection refused / client timeout = the service did NOT answer
        status, reply = None, {"error": type(e).__name__}
    return status, reply, (time.perf_counter() - t0) * 1000


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--url", default="http://localhost:8080/v1/decide")
    p.add_argument("--cards", default="data/cards.jsonl")
    p.add_argument("--budget-ms", type=float, default=50)   # card [5]: "answer in 50 ms"
    p.add_argument("-n", type=int, default=30)
    a = p.parse_args()
    with open(a.cards) as fh:
        card = json.loads(fh.readline())                     # synthetic card from the generator

    print("pausing localstack: DynamoDB + Kinesis frozen")
    compose("pause")
    try:
        rows = []
        for i in range(a.n):                                 # ~6 s: long enough for the breaker to open
            rows.append(send_one(a.url, card, f"dev_down_{i}"))
            time.sleep(0.2)
    finally:
        compose("unpause")
        print("localstack unpaused")

    ok = [r for s, r, _ in rows if s == 200]
    fb = [r for r in ok if r.get("fallback")]
    srv = max((r["latency_ms"] for r in ok), default=float("inf"))
    rt = max(t for *_, t in rows)
    print(f"answered 200: {len(ok)}/{len(rows)}   fallback: {len(fb)}/{len(ok)}")
    print("decisions:", dict(Counter(r["decision"] for r in ok)))
    print("reasons:  ", dict(Counter(x for r in ok for x in r["reasons"])))
    print(f"worst server latency {srv:.1f} ms   worst round trip {rt:.0f} ms")

    start, recovered = time.time(), None                     # breaker stays open up to 5 s after unpause
    while recovered is None and time.time() - start < 30:
        s, r, _ = send_one(a.url, card, "dev_recover")
        if s == 200 and not r.get("fallback"):
            recovered = time.time() - start
        time.sleep(1)

    checks = [("every payment answered while store down", len(ok) == len(rows)),
              ("every answer was a safe fallback", len(fb) == len(ok)),
              (f"server latency within {a.budget_ms:.0f} ms", srv <= a.budget_ms),
              (f"round trip under {RT_LIMIT_MS} ms (Kinesis not blocking)", rt < RT_LIMIT_MS),
              ("normal decisions resume after unpause", recovered is not None)]
    for name, passed in checks:
        print(("PASS " if passed else "FAIL ") + name)
    if recovered is not None:
        print(f"   recovered {recovered:.1f} s after unpause")


if __name__ == "__main__":
    main()
